            }
        }
        return ls.fold(ByteArray(0)) { acc, bytes -> acc + bytes }
    }

    /**
     * 解码
     * @param data ByteArray
     * @return String
     */
    fun decode(data: ByteArray): String {
        var tempByte: Byte? = null
        val sb = StringBuilder()
        for (b in data) {
            val code = if (tempByte != null) {
                val c = byteArrayOf(tempByte, b).toUnsignedInt()
                tempByte = null
                c
            } else if (b.toUnsignedInt() <= 0x7F) {
                b.toUnsignedInt()
            } else {
                tempByte = b
                continue
            }
            if (code in 0x00..0x7F) {
                sb.append(code.toChar())
            } else {
                val i = gbkCode.indexOf(code)
                if (i < 0) {
                    sb.append(Char(65533))
                } else {
                    sb.append(Char(uniCode[i]))
                }
            }
        }
        return sb.toString()
    }
}